/* Prototipo local: agregados reais, navegacao e detalhes. Sem API ou LLM. */
'use strict';
const DATA=window.VERTICE_DATA;
const $=id=>document.getElementById(id);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(v,d=0)=>Number(v).toLocaleString('pt-BR',{minimumFractionDigits:d,maximumFractionDigits:d});
const money=v=>'R$ '+fmt(v,2);
const short=v=>Math.abs(v)>=1e6?'R$ '+fmt(v/1e6,2)+' mi':Math.abs(v)>=1000?'R$ '+fmt(v/1000,1)+' mil':money(v);
const centerValue=(v,key)=>{if(key==='rate')return [fmt(v,2),'%'];if(key==='orders')return [fmt(v),''];return Math.abs(v)>=1e6?['R$ '+fmt(v/1e6,2),'mi']:Math.abs(v)>=1000?['R$ '+fmt(v/1000,1),'mil']:[money(v),''];};
const pct=v=>fmt(v,2)+'%';
const COVERAGE_END='2024-01-01';
const MONTHS=['Jan','Fev','Mar','Abr','Mai','Jun','Jul','Ago','Set','Out','Nov','Dez'];
const COLORS=['#219b91','#7664d8','#5b8fc9','#a5b8d2','#e8bb75','#a597d4','#78b8aa'];
const METRICS={revenue:{label:'Receita líquida',symbol:'R'},margin:{label:'Margem absoluta',symbol:'M'},rate:{label:'Margem percentual',symbol:'%'},orders:{label:'Pedidos',symbol:'#'},ticket:{label:'Ticket médio',symbol:'T'}};
const ICONS={saude:'M3 10l9-7 9 7v10H3z M9 20v-7h6v7',tendencias:'M3 3v18h18 M6 15l5-5 4 3 6-8',alertas:'M12 3L2 21h20z M12 9v5 M12 17v1',hipoteses:'M9 18h6 M10 21h4 M8 14a7 7 0 1 1 8 0l-1 3H9z',relatorio:'M5 2h10l4 4v16H5z M14 2v5h5 M8 12h8 M8 16h8'};
const SECTIONS={saude:['Saúde do negócio','O essencial para entender o negócio e escolher o próximo passo.'],tendencias:['Evolução e tendências','Entenda os movimentos por trás dos indicadores.'],alertas:['Alertas prioritários','Sinais relevantes, com contexto e evidências para investigar.'],hipoteses:['Hipóteses e métricas','Uma base de conhecimento que acompanha cada decisão.'],relatorio:['Relatório executivo','A mesma visão do negócio, organizada para compartilhar.']};
const state={section:'saude',view:'general',frontMetric:'revenue',frontTrendMetric:'',grain:'year',period:'2023',compare:'none',channelMetric:'revenue',categoryMetric:'revenue',trendMetric:'revenue',channel:'all',category:'all'};
let remote={key:'',health:null,trend:null,channels:null,categories:null};
let requestSeq=0;
const icon=k=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.55" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${ICONS[k]}"/></svg>`;
const months=()=>state.grain==='year'?Array.from({length:12},(_,i)=>i+1):state.grain==='quarter'?(()=>{const q=Number(state.period.slice(-1));return [q*3-2,q*3-1,q*3]})():state.grain==='month'?[Number(state.period.slice(-2))]:[1];
const periodLabel=()=>$('period').selectedOptions[0].text;
const context=()=>`${periodLabel()}  -  ${state.channel==='all'?'Todos os canais':state.channel}  -  ${state.category==='all'?'Todas as categorias':state.category}`;
function rangeFor(value=state.period,grain=state.grain){if(grain==='year')return ['2023-01-01','2024-01-01'];if(grain==='quarter'){const q=Number(value.slice(-1)),m=(q-1)*3+1;return [`2023-${String(m).padStart(2,'0')}-01`,q===4?'2024-01-01':`2023-${String(m+3).padStart(2,'0')}-01`];}if(grain==='month'){const m=Number(value.slice(-2));return [`2023-${String(m).padStart(2,'0')}-01`,m===12?'2024-01-01':`2023-${String(m+1).padStart(2,'0')}-01`];}const week=Number(value.slice(-2)),start=new Date(Date.UTC(2023,0,1+(week-1)*7)),end=new Date(start);end.setUTCDate(end.getUTCDate()+7);const fim=end.toISOString().slice(0,10);return [start.toISOString().slice(0,10),fim>COVERAGE_END?COVERAGE_END:fim];}
// A semana 53 comeca em 31/12/2023 e avancaria por 2024, onde nao ha base.
// O intervalo e cortado na cobertura; sem isso o grafico desenharia seis dias
// zerados como se fossem dias sem venda.
function weekPartial(value=state.period,grain=state.grain){if(grain!=='week')return false;const week=Number(value.slice(-2)),end=new Date(Date.UTC(2023,0,1+(week-1)*7));end.setUTCDate(end.getUTCDate()+7);return end.toISOString().slice(0,10)>COVERAGE_END;}
function rowsBetween(start,end,channel=state.channel,category=state.category){return (DATA.daily_rows||[]).filter(row=>{const day=row.date.slice(0,10);return day>=start&&day<end&&(channel==='all'||row.canal===channel)&&(category==='all'||row.categoria===category);});}
function rows(channel=state.channel,ms=null){if(state.grain==='week'&&!ms){const [start,end]=rangeFor();return rowsBetween(start,end,channel);}const selected=ms||months();return DATA.rows.filter(r=>selected.includes(r.month)&&(channel==='all'||r.canal===channel)&&(state.category==='all'||r.categoria===state.category));}
function aggregate(rs){const a={revenue:0,margin:0,orders:0,product:0,freight:0,discount:0,gross:0};rs.forEach(r=>Object.keys(a).forEach(k=>a[k]+=r[k]));a.rate=a.revenue?a.margin/a.revenue*100:0;a.ticket=a.orders?a.revenue/a.orders:0;return a;}
function dailySeries(start,end){const out=[];for(let d=new Date(`${start}T00:00:00Z`);d<new Date(`${end}T00:00:00Z`);d.setUTCDate(d.getUTCDate()+1)){const key=d.toISOString().slice(0,10),next=new Date(d);next.setUTCDate(next.getUTCDate()+1);out.push({month:d.getUTCMonth()+1,date:key,label:String(d.getUTCDate()),...aggregate(rowsBetween(key,next.toISOString().slice(0,10)))});}return out;}
function series(){if(state.grain==='week'||state.grain==='month'){const [start,end]=rangeFor();return dailySeries(start,end);}return months().map(m=>({month:m,label:MONTHS[m-1],...aggregate(rows(state.channel,[m]))}));}
function displaySeries(){return (state.grain==='year'||state.grain==='quarter')&&apiMatches()?(remote.trend?.points||series()):series();}
function byChannel(){return DATA.channels.filter(c=>state.channel==='all'||c===state.channel).map(name=>({name,...aggregate(rows(name))})).sort((a,b)=>b.revenue-a.revenue);}
function benchmark(){return aggregate(rows('all')).rate;}
function focus(){const a=byChannel();return a.find(x=>x.name==='Marketplace')||a.reduce((p,c)=>c.rate<p.rate?c:p,a[0]);}
function previous(){if(state.compare==='none'||state.grain==='year')return null;if(state.grain==='quarter'){const q=Number(state.period.slice(-1));if(q===1)return null;return aggregate(rows(state.channel,[(q-2)*3+1,(q-2)*3+2,(q-2)*3+3]));}if(state.grain==='month'){const m=Number(state.period.slice(-2));if(m===1)return null;return aggregate(rows(state.channel,[m-1]));}const week=Number(state.period.slice(-2));if(week<=1||weekPartial())return null;const [start]=rangeFor(),end=new Date(`${start}T00:00:00Z`),begin=new Date(end);begin.setUTCDate(begin.getUTCDate()-7);return aggregate(rowsBetween(begin.toISOString().slice(0,10),end.toISOString().slice(0,10)));}
function comparisonSeries(){if(state.compare==='none'||state.grain==='year')return [];if(state.grain==='quarter'){const q=Number(state.period.slice(-1));if(q<=1)return [];return [(q-2)*3+1,(q-2)*3+2,(q-2)*3+3].map(month=>({month,label:MONTHS[month-1],...aggregate(rows(state.channel,[month]))}));}if(state.grain==='month'){const month=Number(state.period.slice(-2));if(month<=1)return [];const start=`2023-${String(month-1).padStart(2,'0')}-01`,end=`2023-${String(month).padStart(2,'0')}-01`;return dailySeries(start,end);}const week=Number(state.period.slice(-2));if(week<=1||weekPartial())return [];const [currentStart]=rangeFor(),end=new Date(`${currentStart}T00:00:00Z`),start=new Date(end);start.setUTCDate(start.getUTCDate()-7);return dailySeries(start.toISOString().slice(0,10),end.toISOString().slice(0,10));}
function remoteKey(){return JSON.stringify({grain:state.grain,period:state.period,channel:state.channel,category:state.category});}
function queryString(){const [start,end]=rangeFor();const p=new URLSearchParams({year:'2023',grain:state.grain,start,end});if(state.channel!=='all')p.set('channel',state.channel);if(state.category!=='all')p.set('category',state.category);return p.toString();}
function normalizeApi(payload){if(!payload)return payload;if(payload.points&&(state.grain==='month'||state.grain==='week'))return null;const fix=item=>item?({...item,rate:item.rate??item.margin_pct}):item;if(payload.metrics)payload.metrics=fix(payload.metrics);if(payload.points)payload.points=payload.points.map(fix);if(payload.items)payload.items=payload.items.map(fix);return payload;}
function apiMatches(){const c=remote.health?.context||remote.health;if(!c)return false;const [start,end]=rangeFor();return c.grain===state.grain&&c.start===start&&c.end===end&&c.channel===(state.channel==='all'?null:state.channel)&&c.category===(state.category==='all'?null:state.category);}
function setApiStatus(connected){const label=$('api-label'),dot=$('api-dot');if(!label||!dot)return;label.textContent=connected?'API conectada  -  dados tratados':'Dados tratados  -  offline';dot.style.background=connected?'#31ad94':'#b6a16b';}
async function loadApi(){const key=remoteKey(),seq=++requestSeq;remote={key,health:null,trend:null,channels:null,categories:null};setApiStatus(false);try{const query=queryString(),get=endpoint=>fetch(`http://127.0.0.1:8765/api/${endpoint}?${query}`).then(response=>{if(!response.ok)throw Error(endpoint);return response.json()}),[health,trend,channels,categories]=await Promise.all(['health','trend','channels','categories'].map(get));if(seq!==requestSeq||key!==remoteKey())return;remote={key,health:normalizeApi(health),trend:normalizeApi(trend),channels:normalizeApi(channels),categories:normalizeApi(categories)};setApiStatus(true);render(true);}catch{if(seq===requestSeq&&key===remoteKey()){remote={key,health:null,trend:null,channels:null,categories:null};setApiStatus(false);render(true);}}}
const panel=(title,sub,body,action='')=>`<section class="panel"><div class="panel-header"><div><h2>${title}</h2><p>${sub}</p></div>${action}</div>${body}</section>`;
const navButton=(section,label)=>`<button class="text-button" data-nav="${section}">${label} -></button>`;
function spark(values,color='#168f88'){if(values.length<2)return '';const lo=Math.min(...values),hi=Math.max(...values);const points=values.map((v,i)=>`${i*60/(values.length-1)},${21-(v-lo)/(hi-lo||1)*18}`).join(' ');return `<svg class="spark" viewBox="0 0 62 24" aria-hidden="true"><polyline fill="none" stroke="${color}" stroke-width="1.8" points="${points}"/></svg>`;}
function formatMetric(value,key,compact=false){if(key==='rate')return pct(value);if(key==='orders')return fmt(value);return compact?short(value):money(value);}
function kpis(){const a=apiMatches()&&remote.health?.metrics?remote.health.metrics:aggregate(rows()),p=previous(),s=displaySeries(),showComparison=state.compare!=='none';return `<div class="kpis">${Object.entries(METRICS).map(([key,meta])=>{let comparison='';if(showComparison){if(p){const val=key==='rate'?a[key]-p[key]:p[key]?(a[key]-p[key])/p[key]*100:0;comparison=`<small class="${val>=0?'up':'down'}">${val>=0?'+':''}${fmt(val,1)}${key==='rate'?' p.p.':'%'} vs. período anterior</small>`;}else comparison='<small>Sem base no período anterior</small>';}const bottom=showComparison?`<div class="kpi-bottom">${comparison}${spark(s.map(v=>v[key]),key==='rate'?'#7664dd':'#168f88')}</div>`:'';return `<button class="kpi" data-metric="${key}"><div class="kpi-head"><span>${meta.label}</span><span>${meta.symbol}</span></div><strong>${formatMetric(a[key],key,true)}</strong>${bottom}</button>`;}).join('')}</div>`;}
function axisValue(value,key){if(key==='rate')return `${fmt(value,0)}%`;if(key==='orders')return fmt(value,0);return Math.abs(value)>=1e6?`${fmt(value/1e6,1)} mi`:Math.abs(value)>=1000?`${fmt(value/1000,0)} mil`:fmt(value,0);}
function evolution(){const current=displaySeries(),prior=comparisonSeries(),key=state.trendMetric,lineMetric=key==='rate'||key==='ticket',W=620,H=216,left=58,right=20,top=14,bottom=35,plotH=H-top-bottom,plotW=W-left-right,slots=Math.max(current.length,prior.length,1),values=[...current,...prior].map(point=>Number(point[key])||0);let min=key==='rate'?0:Math.min(0,...values),max=key==='rate'?100:Math.max(...values,1);if(key!=='rate'){const padding=(max-min)*.12||1;max+=padding;if(min<0)min-=padding;}const range=max-min||1,x=i=>left+plotW*(i+.5)/slots,y=value=>top+plotH*(max-value)/range,label=point=>point.label||MONTHS[point.month-1],points=data=>data.map((point,i)=>`${x(i)},${y(Number(point[key])||0)}`).join(' ');let svg=`<svg class="chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(METRICS[key].label)} no intervalo selecionado"><defs><linearGradient id="barGradient" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#27a69c"/><stop offset="1" stop-color="#8cd1c7"/></linearGradient></defs>`;for(let i=0;i<=4;i++){const gridY=top+plotH*i/4,value=max-range*i/4;svg+=`<line class="gridline" x1="${left}" x2="${W-right}" y1="${gridY}" y2="${gridY}"/><text x="${left-9}" y="${gridY+3}" text-anchor="end">${axisValue(value,key)}</text>`;}if(prior.length)svg+=`<polyline fill="none" stroke="#9aa5b5" stroke-width="1.8" stroke-dasharray="5 5" points="${points(prior)}"/>`;const barWidth=Math.min(32,plotW/slots*.47);current.forEach((point,i)=>{const value=Number(point[key])||0;if(lineMetric)return;const baseline=y(0),valueY=y(value);svg+=`<rect class="mark" data-month="${point.month}" data-index="${i}" x="${x(i)-barWidth/2}" y="${Math.min(baseline,valueY)}" width="${barWidth}" height="${Math.max(1,Math.abs(baseline-valueY))}" rx="4" fill="url(#barGradient)"><title>${label(point)}: ${formatMetric(value,key,true)}</title></rect>`;});if(lineMetric){svg+=`<polyline fill="none" stroke="#168f88" stroke-width="2.5" points="${points(current)}"/>`;current.forEach((point,i)=>svg+=`<circle class="mark" data-month="${point.month}" data-index="${i}" cx="${x(i)}" cy="${y(Number(point[key])||0)}" r="3.8" fill="white" stroke="#168f88" stroke-width="2"><title>${label(point)}: ${formatMetric(point[key],key,true)}</title></circle>`);}current.forEach((point,i)=>svg+=`<text x="${x(i)}" y="${H-12}" text-anchor="middle">${label(point)}</text>`);return svg+'</svg>';}
function evolutionPanel(){const key=state.trendMetric,unit=state.grain==='year'||state.grain==='quarter'?'mês':'dia',parcial=weekPartial(),hasComparison=comparisonSeries().length>0,legend=`<div class="legend"><span><i style="background:#168f88"></i>${METRICS[key].label}</span>${hasComparison?'<span><i style="background:#9aa5b5"></i>Período anterior</span>':''}</div>`;return panel(`${METRICS[key].label} ao longo do tempo`,`Intervalo exibido: ${esc(periodLabel())}`,`${metricSelect('trend-kpi')}${legend}<div class="chart-wrap">${evolution()}</div><div class="chart-caption"><span>Eixo: ${METRICS[key].label}</span><span>Clique em um ${unit} para detalhar</span></div>${parcial?'<p class="panel-note">Semana parcial: a base cobre até 31/12/2023, então este recorte tem menos de sete dias. A comparação com a semana anterior fica indisponível por não ser equivalente.</p>':''}`,navButton('tendencias','Explorar'));}
function metricSelect(id){return `<label class="panel-select">KPI<select id="${id}">${Object.entries(METRICS).map(([key,meta])=>`<option value="${key}">${meta.label}</option>`).join('')}</select></label>`;}
function channelPanel(){const key=state.channelMetric,title=METRICS[key].label,apiItems=apiMatches()?remote.channels?.items:null,cs=apiItems?apiItems.map(c=>({name:c.channel,...c})):DATA.channels.map(name=>({name,...aggregate(rows(name))})).sort((a,b)=>b.revenue-a.revenue),values=cs.map(c=>c[key]),arcTotal=values.reduce((sum,value)=>sum+Math.max(value,0),0)||1,summary=apiMatches()&&remote.health?.metrics?remote.health.metrics:aggregate(rows()),selected=state.channel!=='all',centerLabel=selected?state.channel:'Total',radius=53,circ=2*Math.PI*radius;let offset=0;const arcs=cs.map((c,i)=>{const length=Math.max(values[i],0)/arcTotal*circ,color=selected&&c.name!==state.channel?'#d8dee7':COLORS[i%COLORS.length],a=`<circle cx="75" cy="75" r="${radius}" fill="none" stroke="${color}" stroke-width="16" stroke-dasharray="${length} ${circ-length}" stroke-dashoffset="${-offset}" transform="rotate(-90 75 75)"><title>${esc(c.name)}: ${formatMetric(values[i],key,true)}</title></circle>`;offset+=length;return a}).join(''),[center,unit]=centerValue(summary[key],key);return panel(`${title} por canal`,`Selecione o KPI para comparar no recorte atual`,`${metricSelect('channel-kpi')}<div class="donut-layout"><svg class="donut" viewBox="0 0 150 150" role="img" aria-label="${esc(title)} por canal; ${selected?`canal ${esc(state.channel)} destacado`:'todos os canais'}">${arcs}<text x="75" y="55" text-anchor="middle" fill="#8d9aac" font-size="7" font-weight="600">${esc(centerLabel).toUpperCase()}</text><text x="75" y="76" text-anchor="middle" fill="#263750" font-size="16" font-weight="650">${center}</text><text x="75" y="92" text-anchor="middle" fill="#8d9aac" font-size="9">${unit}</text></svg><div class="channel-list">${cs.map((c,i)=>{const muted=selected&&c.name!==state.channel;return `<button class="channel-row${muted?' muted':selected?' selected':''}" data-channel-detail="${esc(c.name)}"><i style="background:${muted?'#cfd6e0':COLORS[i%COLORS.length]}"></i><span>${esc(c.name)}</span><b>${formatMetric(c[key],key,true)}</b></button>`}).join('')}</div></div><p class="panel-note">${selected?`${esc(state.channel)} está destacado; os demais canais permanecem como referência.`:'Selecione um canal no filtro para destacá-lo.'}</p>`);}
function insightPanel(){const f=focus(),gap=f.rate-benchmark();return panel('O que merece atenção','Achados observados  -  não são alertas publicados',`<button class="insight" data-insight="gap"><span class="insight-icon"><img class="insight-svg" src="icons/marketplace.svg" alt="" /></span><div><h3>${esc(f.name)} ${gap<0?'abaixo':'em relação'} à referência</h3><p>Margem de ${pct(f.rate)}  -  diferença de ${fmt(gap,2)} p.p.<br>Comparação com a margem consolidada do recorte.</p></div><span class="arrow">-></span></button><button class="insight" data-insight="quality"><span class="insight-icon teal"><img class="insight-svg" src="icons/data-check.svg" alt="" /></span><div><h3>Dados comparáveis, decisões mais claras</h3><p>2023 completo  -  somente pagamentos aprovados.<br>Custos econômicos adicionais ainda não disponíveis.</p></div><span class="arrow">-></span></button>`,navButton('alertas','Ver sinais'));}
function marginTable(){const cs=byChannel();return panel('Eficiência dos canais','Receita e margem precisam ser lidas em conjunto',`<div class="table-wrap"><table><thead><tr><th>CANAL</th><th>RECEITA</th><th>MARGEM %</th></tr></thead><tbody>${cs.slice(0,4).map(c=>`<tr><td><button class="text-button" data-channel-detail="${esc(c.name)}">${esc(c.name)}</button></td><td>${short(c.revenue)}</td><td><span class="bar-track"><span class="bar-fill" style="width:${Math.min(100,c.rate)}%"></span></span>${fmt(c.rate,1)}%</td></tr>`).join('')}</tbody></table></div>`,navButton('tendencias','Todos os canais'));}
function rowsForCategory(category){if(state.grain==='week'){const [start,end]=rangeFor();return rowsBetween(start,end,state.channel,category);}const selected=months();return DATA.rows.filter(r=>selected.includes(r.month)&&(state.channel==='all'||r.canal===state.channel)&&r.categoria===category);}
function byCategory(){return DATA.categories.map(name=>({name,...aggregate(rowsForCategory(name))}));}
function categoryPanel(){const key=state.categoryMetric,title=METRICS[key].label,apiItems=apiMatches()?remote.categories?.items:null,items=(apiItems?apiItems.map(item=>({name:item.category,...item})):byCategory()).sort((a,b)=>b[key]-a[key]),max=Math.max(...items.map(item=>item[key]),1),hasSelection=state.category!=='all';return panel(`${title} por categoria`,`Compare as categorias no período e canal selecionados`,`${metricSelect('category-kpi')}<div class="category-bars">${items.map(item=>`<button class="category-bar-row${hasSelection?(item.name===state.category?' selected':' muted'):''}" data-category-detail="${esc(item.name)}"><span class="category-bar-label">${esc(item.name)}</span><span class="category-bar-track"><span class="category-bar-fill" style="width:${Math.max(item[key]/max*100,item[key]?2:0)}%"></span></span><strong>${formatMetric(item[key],key,true)}</strong></button>`).join('')}</div><p class="panel-note">${hasSelection?'A categoria filtrada está destacada; as demais permanecem como referência.':'Selecione uma categoria para abrir os detalhes.'}</p>`);}
function overview(){return kpis()+`<div class="grid-main">${channelPanel()}${categoryPanel()}</div><div class="grid-bottom">${marginTable()}${insightPanel()}</div>`;}
function trends(){const porMes=state.grain==='year'||state.grain==='quarter',s=displaySeries();return kpis()+`<div class="grid-main">${evolutionPanel()}${channelPanel()}</div>`+panel('Comparação por canal','Mesmo período e categoria  -  a referência mantém todos os canais',`<div class="table-wrap"><table><thead><tr><th>CANAL</th><th>RECEITA</th><th>MARGEM ABSOLUTA</th><th>MARGEM %</th><th>GAP VS. CONSOLIDADO</th></tr></thead><tbody>${byChannel().map(c=>`<tr><td><button class="text-button" data-channel-detail="${esc(c.name)}">${esc(c.name)}</button></td><td>${money(c.revenue)}</td><td>${money(c.margin)}</td><td>${pct(c.rate)}</td><td>${fmt(c.rate-benchmark(),2)} p.p.</td></tr>`).join('')}</tbody></table></div><details class="a11y-table"><summary>Consultar os valores ${porMes?'mensais':'diários'} do gráfico</summary><table><thead><tr><th>${porMes?'MÊS':'DIA'}</th><th>RECEITA</th><th>MARGEM %</th><th>PEDIDOS</th></tr></thead><tbody>${s.map(v=>`<tr><td>${v.label||MONTHS[v.month-1]}</td><td>${money(v.revenue)}</td><td>${pct(v.rate)}</td><td>${fmt(v.orders)}</td></tr>`).join('')}</tbody></table></details>`);}
function hypotheses(){return aiSection();}
