// Monta o documento a partir da mesma camada da interface, como pede docs/07:
// "nenhuma lógica analítica duplicada". Os alertas vêm de /api/alerts, os KPIs
// do agregado local, e a cobertura do snapshot tratado.
function reportPeriodLabel(){return periodLabel().replace(/\s+-\s+/g,' · ');}
function reportKpiRow(){const a=aggregate(rows()),p=priorPeriod();const itens=[['Receita líquida','revenue','money'],['Margem absoluta','margin','money'],['Margem percentual','rate','pct'],['Pedidos','orders','int'],['Ticket médio','ticket','money']];return `<table><thead><tr><th>INDICADOR</th><th>VALOR</th><th>PERÍODO ANTERIOR</th><th>VARIAÇÃO</th></tr></thead><tbody>${itens.map(([rotulo,chave,unidade])=>{const atual=a[chave],ant=p?p[chave]:null;let variacao='<span class="cell-empty">sem base anterior</span>';if(p&&ant){const d=chave==='rate'?atual-ant:(atual-ant)/Math.abs(ant)*100;variacao=`<span class="${d>=0?'up':'down'}">${d>=0?'+':''}${fmt(d,2)}${chave==='rate'?' p.p.':'%'}</span>`;}const exibir=v=>v===null||v===undefined?'—':unidade==='money'?money(v):unidade==='pct'?pct(v):fmt(v);return `<tr><td>${rotulo}</td><td><b>${exibir(atual)}</b></td><td>${p?exibir(ant):'—'}</td><td>${variacao}</td></tr>`;}).join('')}</tbody></table>`;}
function reportAlerts(){const d=alertState.data;if(alertState.error)return `<p>Não foi possível avaliar as regras: ${esc(alertState.error)}</p>`;if(!d)return '<p>Avaliando as regras de alerta…</p>';const publicados=d.alerts.filter(a=>a.severity!=='Informativa');if(!publicados.length)return `<p>Nenhuma condição superou a materialidade de ${money(d.parameters.materialidade_brl)} e as tolerâncias vigentes neste recorte. Isso não comprova ausência de problemas: veja o catálogo de regras na seção Alertas prioritários.</p>`;return `<table><thead><tr><th>REGRA</th><th>SEVERIDADE</th><th>ACHADO</th><th>IMPACTO DIAGNÓSTICO</th></tr></thead><tbody>${publicados.map(a=>`<tr><td>${esc(a.rule)}</td><td>${esc(a.severity)}</td><td>${esc(a.title)}</td><td>${a.impact===null||a.impact===undefined?'—':money(a.impact)}</td></tr>`).join('')}</tbody></table>`;}
function reportChannels(){const cs=byChannel(),ref=benchmark();return `<table><thead><tr><th>CANAL</th><th>RECEITA</th><th>MARGEM %</th><th>GAP VS. CONSOLIDADO</th></tr></thead><tbody>${cs.map(c=>`<tr><td>${esc(c.name)}</td><td>${money(c.revenue)}</td><td>${pct(c.rate)}</td><td>${fmt(c.rate-ref,2)} p.p.</td></tr>`).join('')}</tbody></table>`;}
function reportLimits(){const d=alertState.data;const base=['A margem é receita líquida menos custo de produto e frete: não inclui comissões, impostos nem o efeito financeiro de devoluções.','Os dados são observacionais. Variação entre períodos e diferença entre cortes não demonstram causa.','Um único ciclo anual não permite separar sazonalidade de deterioração.'];const extra=d?(d.alerts.find(a=>a.rule==='Q01')?.evidence||[]).map(e=>`${e.rotulo}: ${fmt(e.valor)}`):[];return `<ul class="ai-list">${base.map(l=>`<li>${esc(l)}</li>`).join('')}${extra.length?`<li>Limitações de cobertura registradas no snapshot: ${esc(extra.join('; '))}.</li>`:''}</ul>`;}
function report(){const emitido=new Date().toLocaleDateString('pt-BR');const capa=`<div class="report-head"><div><div class="eyebrow">RELATÓRIO EXECUTIVO</div><h2>Vértice Retail — ${esc(reportPeriodLabel())}</h2><p>${esc(context())}</p></div><div class="report-meta"><div><span>EMITIDO EM</span><b>${emitido}</b></div><div><span>BASE TRATADA</span><b>${esc(DATA.processed_snapshot)}</b></div><div><span>POPULAÇÃO</span><b>Aprovado; medidas completas</b></div></div></div>`;const secoes=[['01','Saúde do negócio',reportKpiRow()],['02','O que merece atenção',reportAlerts()],['03','Leitura por canal',reportChannels()],['04','Limites desta edição',reportLimits()]].map(([n,t,corpo])=>`<section class="report-block"><div class="eyebrow">${n}</div><h3>${t}</h3><div class="table-wrap">${corpo}</div></section>`).join('');return `<div class="section-intro">O relatório usa a mesma camada analítica da interface e respeita os filtros selecionados. Nenhum número é recalculado aqui.<div class="detail-actions" style="margin-top:14px"><button class="primary" id="report-pdf">Gerar resumo em PDF</button><button class="secondary" data-nav="alertas">Ver catálogo de regras</button></div></div><article id="report-doc" class="report-doc">${capa}${secoes}<footer class="report-foot">Vértice Retail · ${esc(reportPeriodLabel())} · base tratada ${esc(DATA.processed_snapshot)} · emitido em ${emitido}. Margem = receita líquida − custo de produto − frete.</footer></article>`;}
// Sem biblioteca externa: a folha de impressão isola o documento e o navegador
// oferece "Salvar como PDF". É o que mantém a promessa de docs/11 de não exigir
// dependência remota.
document.addEventListener('click',evento=>{if(!evento.target.closest('#report-pdf'))return;if(!alertState.data&&!alertState.error){loadAlerts();}document.body.classList.add('imprimindo');const limpar=()=>document.body.classList.remove('imprimindo');window.addEventListener('afterprint',limpar,{once:true});setTimeout(()=>{window.print();setTimeout(limpar,500);},60);});
function navigate(section){if(!SECTIONS[section])section='saude';state.section=section;location.hash=section;render();window.scrollTo({top:0,behavior:'instant'});}
function render(fromApi=false){if(!fromApi&&FRONT_SECTIONS.includes(state.section)&&state.view!=='general'&&frontState.key!==frontKey())setTimeout(loadFront,0);if(!fromApi&&(state.section==='alertas'||state.section==='relatorio')&&alertState.key!==alertKey())setTimeout(loadAlerts,0);const key=remoteKey(),needsApi=!fromApi&&remote.key!==key;if(needsApi){remote={key,health:null,trend:null,channels:null,categories:null};setApiStatus(false);}document.body.dataset.section=state.section;const [title,sub]=SECTIONS[state.section];$('title').textContent=title;$('subtitle').textContent=sub;$('crumb').textContent=title;document.title=`Vértice  -  ${title}`;$('nav').innerHTML=Object.entries(SECTIONS).map(([k,v])=>`<button data-nav="${k}" class="${state.section===k?'active':''}" ${state.section===k?'aria-current="page"':''} aria-label="${v[0]}" title="${v[0]}">${icon(k)}<span class="nav-text">${v[0]}</span></button>`).join('');frontTabs();const foco=document.activeElement,digitando=foco&&foco.id==='ai-question'?{ini:foco.selectionStart,fim:foco.selectionEnd}:null;$('content').innerHTML=(FRONT_SECTIONS.includes(state.section)&&state.view!=='general')?(state.section==='tendencias'?frontTrendView():frontView()):({saude:overview,tendencias:trends,alertas:alerts,hipoteses:hypotheses,relatorio:report}[state.section])();decorateMetricMenus();if(digitando){const campo=$('ai-question');if(campo){campo.focus();try{campo.setSelectionRange(digitando.ini,digitando.fim);}catch{}}}if(needsApi)loadApi();}
function drawer(title,html,label='DETALHAMENTO'){$('drawer-label').textContent=label;$('drawer-content').innerHTML=`<h2>${title}</h2>${html}`;if(!$('detail').open)$('detail').showModal();}
function facts(){drawer('Dados reais. Limites explícitos.',`<p>Este protótipo usa 336 agregados mensais de vendas aprovadas em 2023, calculados sobre a base tratada e verificada. Nenhum CSV original foi modificado.</p><div class="fact"><b>População anual</b><p>23.388 pedidos  -  receita de R$ 15.966.340,87  -  margem de R$ 8.675.612,00.</p></div><p>Margem = receita líquida âˆ’ custo do produto âˆ’ frete. Não inclui comissão, impostos ou todos os custos econômicos. Taxas são razões de somas.</p><p>Filtros funcionais: período, canal e categoria. SKU e os outros domínios ficam para a implementação; este protótipo concentra-se na jornada comercial.</p><p>Alertas são candidatos, planos são rascunhos e IA é um roteiro demonstrativo. Não há API, salvamento de ações, modelo de IA ou envio de relatórios.</p><p>Base tratada: ${esc(DATA.processed_snapshot)}<br>Origem preservada: vendas.csv  -  SHA-256</p><small style="overflow-wrap:anywhere">${DATA.source_sha256}</small><div class="detail-actions"><a class="text-button" href="../10-contrato-inicial-e-calibracao.md">Contrato analítico -></a></div>`,'FONTES E METODOLOGIA');}
function metricDetail(key){const a=aggregate(rows()),labels={revenue:'Receita líquida',margin:'Margem absoluta',rate:'Margem percentual',orders:'Pedidos',ticket:'Ticket médio'},formula={revenue:'Soma de receita_liquida dos pagamentos aprovados.',margin:'Soma da receita líquida menos custo do produto e frete.',rate:'Margem absoluta dividida pela receita líquida. Razão de somas, não média de percentuais.',orders:'Contagem de pedidos distintos. Cada pedido tem uma linha nesta base.',ticket:'Receita líquida dividida pelos pedidos aprovados.'};drawer(labels[key],`<p>${esc(context())}</p><div class="detail-value">${key==='rate'?pct(a[key]):key==='orders'?fmt(a[key]):money(a[key])}</div><div class="fact"><b>Como é calculado</b><p>${formula[key]}</p></div><p>Dados históricos. Uma variação observada não demonstra causa. Custos econômicos ausentes não são substituídos por zero.</p><div class="detail-actions"><button class="primary" data-nav="tendencias">Explorar tendência -></button><button class="secondary" data-ai>Investigar  -  roteiro IA</button></div>`);}
function channelDetail(name){const a=aggregate(rows(name)),b=benchmark(),total=aggregate(rows('all')).revenue;drawer(esc(name),`<p>${esc(periodLabel())}  -  ${esc(state.category==='all'?'Todas as categorias':state.category)}  -  aprovados</p><div class="detail-value">${pct(a.rate)}</div><p>Margem percentual</p><dl><dt>Receita líquida</dt><dd>${money(a.revenue)}</dd><dt>Margem absoluta</dt><dd>${money(a.margin)}</dd><dt>Participação na receita</dt><dd>${pct(a.revenue/total*100)}</dd><dt>Pedidos</dt><dd>${fmt(a.orders)}</dd><dt>Benchmark consolidado</dt><dd>${pct(b)}</dd><dt>Gap para referência</dt><dd>${fmt(a.rate-b,2)} p.p.</dd></dl><div class="fact"><b>Composição observada</b><p>Produto / receita: ${pct(a.product/a.revenue*100)}<br>Frete / receita: ${pct(a.freight/a.revenue*100)}<br>Desconto / receita bruta: ${pct(a.discount/a.gross*100)}</p></div><p>A referência mantém todos os canais no mesmo período e categoria. Não é meta aprovada nem ganho garantido.</p><div class="detail-actions"><button class="primary" data-apply-channel="${esc(name)}">Filtrar este canal -></button></div>`,'DETALHE DO CANAL');}
function categoryDetail(name){const a=aggregate(rowsForCategory(name)),total=aggregate(DATA.categories.flatMap(rowsForCategory));drawer(esc(name),`<p>${esc(periodLabel())}  -  ${esc(state.channel==='all'?'Todos os canais':state.channel)}  -  pagamentos aprovados</p><div class="detail-value">${short(a.revenue)}</div><p>Receita líquida</p><dl><dt>Margem absoluta</dt><dd>${money(a.margin)}</dd><dt>Margem percentual</dt><dd>${pct(a.rate)}</dd><dt>Pedidos</dt><dd>${fmt(a.orders)}</dd><dt>Ticket médio</dt><dd>${money(a.ticket)}</dd><dt>Participação na receita</dt><dd>${pct(total.revenue?a.revenue/total.revenue*100:0)}</dd></dl><p>Comparação descritiva no mesmo período e canal. Os valores observados não demonstram causalidade.</p><div class="detail-actions"><button class="primary" data-apply-category="${esc(name)}">Filtrar esta categoria -></button></div>`,'DETALHE DA CATEGORIA');}
function gapDetail(){const f=focus();drawer('Eficiência merece investigação',`<span class="pill amber">Candidato  -  não publicado</span><p>${esc(context())}</p><div class="fact"><b>${esc(f.name)}</b><p>Margem ${pct(f.rate)} frente a ${pct(benchmark())} no consolidado. Gap: ${fmt(f.rate-benchmark(),2)} p.p.</p></div><p>O valor é uma comparação observada. Materialidade, persistência e prioridade ainda precisam de calibração. Não é evidência suficiente para cortar canal ou descontos.</p><div class="detail-actions"><button class="primary" data-channel-detail="${esc(f.name)}">Decompor indicador -></button></div>`,'EVIDÊNCIA DO SINAL');}
document.addEventListener('click',event=>{const target=event.target.closest('button,[data-month]');if(!target)return;const d=target.dataset;if(d.nav){$('detail').close();navigate(d.nav);}else if(d.metric)metricDetail(d.metric);else if(d.channelDetail)channelDetail(d.channelDetail);else if(d.categoryDetail)categoryDetail(d.categoryDetail);else if(d.applyCategory){state.category=d.applyCategory;$('category').value=state.category;$('detail').close();render();}else if(d.applyChannel){state.channel=d.applyChannel;$('channel').value=state.channel;$('detail').close();navigate('tendencias');}else if(d.insight==='gap')gapDetail();else if(d.insight==='quality')facts();else if(d.month){const a=aggregate(rows(state.channel,[Number(d.month)]));drawer(`${MONTHS[Number(d.month)-1]} de 2023`,`<p>${esc(state.channel==='all'?'Todos os canais':state.channel)}  -  ${esc(state.category==='all'?'Todas as categorias':state.category)}</p><dl><dt>Receita líquida</dt><dd>${money(a.revenue)}</dd><dt>Margem absoluta</dt><dd>${money(a.margin)}</dd><dt>Margem percentual</dt><dd>${pct(a.rate)}</dd><dt>Pedidos</dt><dd>${fmt(a.orders)}</dd></dl><p>População aprovada e mês completo. Valores observados, sem atribuição causal.</p>`,'PONTO DA SÉRIE');}else if('ai'in d){$('detail').close();abrirInvestigacao();}});
for(const [id,values]of [['channel',DATA.channels],['category',DATA.categories]])values.forEach(v=>{const option=document.createElement('option');option.value=v;option.textContent=v;$(id).append(option);});
// A granularidade vem do formato do valor: 2023 | 2023-Q3 | 2023-07 | 2023-W30.
function periodGrain(value){return String(value).includes('-W')?'week':String(value).includes('-Q')?'quarter':String(value).length===7?'month':'year';}
function syncPeriods(){const sel=$('period'),g=state.grain;let options=[];if(g==='year')options=[['2023','Ano completo  -  2023']];if(g==='quarter')options=Array.from({length:4},(_,i)=>{const q=i+1;return [`2023-Q${q}`,`Trimestre ${q}  -  2023`];});if(g==='month')options=Array.from({length:12},(_,i)=>{const m=i+1;return [`2023-${String(m).padStart(2,'0')}`,`${MONTHS[i]}  -  2023`];});if(g==='week')options=Array.from({length:53},(_,i)=>{const w=i+1,value=`2023-W${String(w).padStart(2,'0')}`,[start,end]=rangeFor(value,'week'),first=new Date(`${start}T00:00:00Z`),last=new Date(`${end}T00:00:00Z`);last.setUTCDate(last.getUTCDate()-1);const interval=first.getUTCMonth()===last.getUTCMonth()?`${first.getUTCDate()} a ${last.getUTCDate()} ${MONTHS[first.getUTCMonth()]}`:`${first.getUTCDate()} ${MONTHS[first.getUTCMonth()]} a ${last.getUTCDate()} ${MONTHS[last.getUTCMonth()]}`;return [value,`Semana ${String(w).padStart(2,'0')}  -  ${interval}${weekPartial(value,'week')?'  -  parcial':''}`];});if(!options.some(x=>x[0]===state.period)){const anterior=rangeFor(state.period,periodGrain(state.period))[0];const alvo=options.find(([value])=>{const [ini,fim]=rangeFor(value,g);return anterior>=ini&&anterior<fim;});state.period=alvo?alvo[0]:(g==='week'?options[51][0]:options[0][0]);}sel.innerHTML=options.map(x=>`<option value="${x[0]}">${x[1]}</option>`).join('');sel.value=state.period;}
syncPeriods();
$('compare').querySelector('[value="avg4"]')?.remove();
for(const id of ['grain','period','compare','channel','category'])$(id).addEventListener('change',()=>{state[id]=$(id).value;if(id==='grain')syncPeriods();render();});
