document.addEventListener('click',event=>{const point=event.target.closest('[data-index]');if(!point)return;document.querySelectorAll('.chart .mark.active').forEach(mark=>mark.classList.remove('active'));point.classList.add('active');const value=displaySeries()[Number(point.dataset.index)];if(!value)return;drawer(`${value.label||MONTHS[value.month-1]} - ${periodLabel()}`,`<dl><dt>Receita líquida</dt><dd>${money(value.revenue)}</dd><dt>Margem absoluta</dt><dd>${money(value.margin)}</dd><dt>Margem percentual</dt><dd>${pct(value.rate)}</dd><dt>Pedidos</dt><dd>${fmt(value.orders)}</dd><dt>Ticket médio</dt><dd>${money(value.ticket)}</dd></dl>`,'PONTO DA SÉRIE');});
function buildMetricMenu(select,stateKey,scopeLabel){const label=select.closest('label');if(!label||label.querySelector('.metric-menu-trigger'))return;const trigger=document.createElement('button');trigger.type='button';trigger.className='metric-menu-trigger';trigger.dataset.metricMenuTrigger='';trigger.setAttribute('aria-label',`Selecionar KPI por ${scopeLabel}`);trigger.setAttribute('aria-haspopup','listbox');trigger.setAttribute('aria-expanded','false');const menu=document.createElement('div');menu.className='metric-menu';menu.setAttribute('role','listbox');menu.setAttribute('aria-label',`KPI exibido por ${scopeLabel}`);menu.innerHTML=Array.from(select.options,option=>`<button type="button" class="metric-menu-option" role="option" data-metric-state="${stateKey}" data-metric-value="${esc(option.value)}" aria-selected="${option.value===state[stateKey]}">${esc(option.textContent)}</button>`).join('');label.append(trigger,menu);}
function decorateMetricSelect(id,stateKey,scopeLabel){const select=$(id);if(!select)return;select.value=state[stateKey];const label=select.closest('label'),heading=select.closest('.panel')?.querySelector('h2');if(!label)return;label.className='panel-select';if(heading&&label.parentElement!==heading)heading.append(label);buildMetricMenu(select,stateKey,scopeLabel);}
function decorateMetricMenus(){decorateMetricSelect('channel-kpi','channelMetric','canal');decorateMetricSelect('category-kpi','categoryMetric','categoria');decorateMetricSelect('trend-kpi','trendMetric','período');decorateMetricSelect('front-metric-kpi','frontMetric','categoria');decorateMetricSelect('front-trend-kpi','frontTrendMetric','período');}
document.addEventListener('click',event=>{const trigger=event.target.closest('[data-metric-menu-trigger]'),option=event.target.closest('[data-metric-value]'),openMenu=document.querySelector('.panel-select.open');if(option){state[option.dataset.metricState]=option.dataset.metricValue;render();return;}if(trigger){const label=trigger.closest('.panel-select'),willOpen=!label.classList.contains('open');openMenu?.classList.remove('open');label.classList.toggle('open',willOpen);trigger.setAttribute('aria-expanded',String(willOpen));return;}if(openMenu){openMenu.classList.remove('open');openMenu.querySelector('[data-metric-menu-trigger]')?.setAttribute('aria-expanded','false');}});
document.addEventListener('keydown',event=>{if(event.key!=='Escape')return;const openMenu=document.querySelector('.panel-select.open');if(!openMenu)return;openMenu.classList.remove('open');const trigger=openMenu.querySelector('[data-metric-menu-trigger]');trigger?.setAttribute('aria-expanded','false');trigger?.focus();});
let aiView='perguntar';
const AI_BASE='http://127.0.0.1:8765';
const aiState={key:'',status:null,suggestions:[],question:'',answer:null,error:null,loading:false};
function aiFilters(){const [start,end]=rangeFor();const filters={year:'2023',grain:state.grain,start,end};if(state.channel!=='all')filters.channel=state.channel;if(state.category!=='all')filters.category=state.category;return filters;}
function aiQuery(){return new URLSearchParams(aiFilters()).toString();}
// Markdown do modelo renderizado por um subconjunto seguro: escapa primeiro, formata depois.
function mdToHtml(md){const lines=esc(md).split('\n');const inline=s=>s.replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>');let html='',list=false,table=false;const closeList=()=>{if(list){html+='</ul>';list=false;}},closeTable=()=>{if(table){html+='</tbody></table></div>';table=false;}};for(const raw of lines){const line=raw.trim();if(!line){closeList();closeTable();continue;}if(line.startsWith('|')){const cells=line.split('|').slice(1,-1).map(c=>c.trim());if(cells.length&&cells.every(c=>/^:?-{2,}:?$/.test(c)))continue;if(!table){closeList();html+='<div class="table-wrap"><table><tbody>';table=true;}html+='<tr>'+cells.map(c=>`<td>${inline(c)}</td>`).join('')+'</tr>';continue;}closeTable();if(line.startsWith('&gt;')){closeList();html+=`<p class="ai-callout">${inline(line.replace(/^&gt;\s*/,''))}</p>`;continue;}const heading=line.match(/^#{2,4}\s+(.*)$/);if(heading){closeList();html+=`<h3 class="ai-heading">${inline(heading[1])}</h3>`;continue;}if(/^[-*]\s+/.test(line)){if(!list){html+='<ul class="ai-list">';list=true;}html+=`<li>${inline(line.replace(/^[-*]\s+/,''))}</li>`;continue;}closeList();html+=`<p>${inline(line)}</p>`;}closeList();closeTable();return html;}
async function aiLoadContext(){const key=remoteKey();if(aiState.key===key&&aiState.status)return;aiState.key=key;aiState.answer=null;aiState.error=null;aiState.suggestions=[];try{const [status,suggestions]=await Promise.all([fetch(`${AI_BASE}/api/ai/status`).then(r=>r.json()),fetch(`${AI_BASE}/api/ai/suggestions?${aiQuery()}`).then(r=>r.json())]);aiState.status=status;aiState.suggestions=suggestions.items||[];}catch{aiState.status={available:false,reason:'API analítica offline; inicie python3 -m app.server'};}if(state.section==='hipoteses')render(true);}
async function aiSend(question){question=(question||'').trim();if(!question||aiState.loading)return;aiState.question=question;aiState.loading=true;aiState.error=null;aiState.answer=null;render(true);try{const response=await fetch(`${AI_BASE}/api/ai/investigate`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question,filters:aiFilters()})});const data=await response.json();if(!response.ok)throw Error(data.error||`erro HTTP ${response.status}`);aiState.answer=data;}catch(error){aiState.error=String(error.message||error).replace(/^Error:\s*/,'');}aiState.loading=false;render(true);}
// O botão do cabeçalho leva à seção; já estando nela, leva o foco à caixa.
function abrirInvestigacao(){if(state.section!=='hipoteses'){navigate('hipoteses');setTimeout(abrirInvestigacao,120);return;}if(aiView!=='perguntar'){aiView='perguntar';render();}const campo=$('ai-question');if(campo){campo.scrollIntoView({behavior:'smooth',block:'center'});campo.focus();}}
function aiStatusPill(){const s=aiState.status;if(!s)return '<span class="pill amber">Verificando IA…</span>';if(s.mode==='offline')return '<span class="pill purple">Modo offline · sem consumo de tokens</span>';return s.available?`<span class="pill teal">IA conectada · ${esc(s.model||'')}</span>`:'<span class="pill amber">IA indisponível · roteiro determinístico</span>';}
function aiAskPanel(){const s=aiState.status,off=!s||!s.available;const chips=aiState.suggestions.length?`<p class="ai-label">Hipóteses sugeridas para este recorte</p><div class="ai-suggestions">${aiState.suggestions.map(item=>`<button class="ai-chip" data-ai-ask="${esc(item.question)}"><b>${esc(item.label)}</b><span>${esc(item.question)}</span></button>`).join('')}</div>`:'';const form=`<p class="ai-label">Ou pergunte com suas palavras</p><textarea id="ai-question" rows="3" placeholder="Ex.: qual categoria puxa a margem para baixo neste canal?" ${off?'disabled':''}>${esc(aiState.question)}</textarea><div class="ai-ask-actions"><small>${off?esc(s&&s.reason||'IA não configurada no servidor'):s.mode==='offline'?'Resposta montada localmente pela camada analítica; nenhum token é consumido.':'A IA responde apenas com os dados deste recorte.'}</small><button class="primary" id="ai-send" ${off||aiState.loading?'disabled':''}>${aiState.loading?'Consultando…':'Perguntar'}</button></div>`;let result='';const offline=aiState.answer?.mode==='offline';if(aiState.loading)result=`<div class="ai-loading">Consultando a IA sobre ${esc(context())}…</div>`;else if(aiState.error)result=`<div class="ai-error"><b>Não foi possível responder</b><p>${esc(aiState.error)}</p><p>As abas Resumo, Canais e Categorias continuam disponíveis sem IA.</p></div>`;else if(aiState.answer)result=`<div class="ai-answer${offline?' offline':''}"><div class="ai-answer-head"><span class="pill ${offline?'amber':'purple'}">${offline?'Resposta local · sem IA':'Resposta da IA'}</span><small>${esc(aiState.answer.model)} · ${esc(aiState.answer.scope.label)}</small></div>${mdToHtml(aiState.answer.answer)}<p class="panel-note">${offline?'Modo offline: nenhum provedor foi chamado. Os números vêm da camada analítica; a leitura da pergunta, não.':'Os números são calculados pela camada analítica e entregues prontos ao modelo; ele não consulta a base por conta própria e não busca na web.'}</p></div>`;return chips+form+result;}
function aiSection(){const destaque=(alertState.data?.alerts||[]).find(a=>a.navigate&&a.navigate.metric),key=state.section==='tendencias'?state.trendMetric:(destaque?.navigate.metric||'rate'),current=aggregate(rows()),prior=priorPeriod(),metric=METRICS[key],delta=prior?(key==='rate'?current[key]-prior[key]:prior[key]?(current[key]-prior[key])/prior[key]*100:0):null,channels=byChannel().sort((a,b)=>a[key]-b[key]),categories=byCategory().sort((a,b)=>a[key]-b[key]),lowestChannel=channels[0],highestChannel=channels.at(-1),lowestCategory=categories[0],highestCategory=categories.at(-1),change=delta===null?'Não há período anterior comparável.':key==='rate'?`${delta>=0?'+':''}${fmt(delta,1)} p.p.`:`${delta>=0?'+':''}${fmt(delta,1)}%`;let body='';if(aiView==='perguntar')body=aiAskPanel();else if(aiView==='canais')body=`<div class="fact"><b>Comparação por canal</b><p>Este recorte mantém ${esc(periodLabel())} e ${esc(state.category==='all'?'todas as categorias':state.category)}.</p><table><thead><tr><th>CANAL</th><th>${metric.label.toUpperCase()}</th><th>LEITURA</th></tr></thead><tbody>${channels.map((item,index)=>`<tr><td>${esc(item.name)}</td><td>${formatMetric(item[key],key,true)}</td><td>${index===0?'Menor valor observado':index===channels.length-1?'Maior valor observado':'Intermediário'}</td></tr>`).join('')}</tbody></table></div><p><b>Hipótese para teste</b><br>O mix de canais pode estar associado à variação agregada. Compare composição, custos disponíveis e mix de produto antes de recomendar uma intervenção.</p>`;else if(aiView==='categorias')body=`<div class="fact"><b>Comparação por categoria</b><p>Este recorte mantém ${esc(periodLabel())} e ${esc(state.channel==='all'?'todos os canais':state.channel)}.</p><table><thead><tr><th>CATEGORIA</th><th>${metric.label.toUpperCase()}</th><th>LEITURA</th></tr></thead><tbody>${categories.map((item,index)=>`<tr><td>${esc(item.name)}</td><td>${formatMetric(item[key],key,true)}</td><td>${index===0?'Menor valor observado':index===categories.length-1?'Maior valor observado':'Intermediário'}</td></tr>`).join('')}</tbody></table></div><p><b>Hipótese para teste</b><br>O mix de categorias pode ajudar a contextualizar o resultado. A comparação é descritiva e não demonstra que a categoria causou a variação.</p>`;else body=`<div class="fact"><b>Fato observado</b><p>${metric.label} no recorte atual: <b>${formatMetric(current[key],key,true)}</b>${prior?`; período anterior: <b>${formatMetric(prior[key],key,true)}</b>; variação: <b>${change}</b>.`:'.'}</p></div><div class="fact"><b>Cortes que merecem investigação</b><p>${lowestChannel&&highestChannel?`Por canal, ${esc(lowestChannel.name)} tem o menor valor observado (${formatMetric(lowestChannel[key],key,true)}) e ${esc(highestChannel.name)} o maior (${formatMetric(highestChannel[key],key,true)}).`:''}<br>${lowestCategory&&highestCategory?`Por categoria, ${esc(lowestCategory.name)} tem o menor valor observado (${formatMetric(lowestCategory[key],key,true)}) e ${esc(highestCategory.name)} o maior (${formatMetric(highestCategory[key],key,true)}).`:''}</p></div><p><b>Hipótese</b><br>Diferenças de mix, canal, categoria ou composição de custos podem estar relacionadas ao resultado. Esta é uma hipótese de investigação, não uma conclusão causal.</p>`;const tabs=[['perguntar','Perguntar'],['resumo','Resumo'],['canais','Canais'],['categorias','Categorias']];const footer=aiView==='perguntar'?'':`<div class="divider"></div><p><b>Limitações</b><br>Os dados são observacionais e não incluem todos os custos econômicos. Variações e diferenças entre segmentos não comprovam causalidade.</p><p><b>Próxima investigação sugerida</b><br>Ver a evolução do KPI e decompor produto, frete e desconto no segmento selecionado.</p>`;setTimeout(aiLoadContext,0);return `<div class="section-intro">Pergunte sobre o recorte selecionado. A IA responde apenas com os números da camada analítica.<br>${esc(context())}</div><div class="ai-status">${aiStatusPill()}</div><div class="ai-tabs">${tabs.map(([id,label])=>`<button class="${aiView===id?'active':''}" data-ai-view="${id}">${label}</button>`).join('')}</div>${panel(`Investigar ${esc(metric.label)}`,'Investigação assistida sobre o recorte atual',`${body}${footer}<div class="detail-actions"><button class="primary" data-ai-open-trend="${key}">Abrir tendência</button><button class="secondary" data-ai-view="resumo">Ver leitura determinística</button></div>`)}`;}
document.addEventListener('click',event=>{const view=event.target.closest('[data-ai-view]'),trend=event.target.closest('[data-ai-open-trend]'),chip=event.target.closest('[data-ai-ask]'),send=event.target.closest('#ai-send');if(chip){aiSend(chip.dataset.aiAsk);return;}if(send){aiSend(($('ai-question')||{}).value||aiState.question);return;}if(view){aiView=view.dataset.aiView;render(true);}if(trend){state.trendMetric=trend.dataset.aiOpenTrend;state.compare='previous';$('compare').value='previous';$('detail').close();navigate('tendencias');}});
document.addEventListener('input',event=>{if(event.target.id==='ai-question')aiState.question=event.target.value;});
document.addEventListener('keydown',event=>{if(event.target.id==='ai-question'&&event.key==='Enter'&&(event.ctrlKey||event.metaKey)){event.preventDefault();aiSend(event.target.value);}});
// --- Frentes de negócio na Saúde do negócio -------------------------------
// Configuração central: uma frente é uma entrada aqui, não um ramo de if.
// "Geral" é a visão comercial já existente e não consulta a API de frentes.
const BUSINESS_VIEWS={general:{label:'Geral',remote:false},sales:{label:'Vendas',remote:true},marketing:{label:'Marketing',remote:true},inventory:{label:'Estoque',remote:true},support:{label:'Atendimento',remote:true}};
const frontState={key:'',view:'',data:null,loading:false,error:null};
// Estoque é fotografia sem data: período e canal não entram na chave do cache.
function frontKey(){const [start,end]=rangeFor();return JSON.stringify(state.view==='inventory'?{v:state.view,category:state.category}:{v:state.view,start,end,grain:state.grain,channel:state.channel,category:state.category});}
function frontQuery(){const [start,end]=rangeFor();const p=new URLSearchParams({year:'2023',grain:state.grain,start,end});if(state.channel!=='all')p.set('channel',state.channel);if(state.category!=='all')p.set('category',state.category);return p.toString();}
const FRONT_SECTIONS=['saude','tendencias'];
function frontTabs(){const box=$('fronts');if(!box)return;const ativo=FRONT_SECTIONS.includes(state.section);box.hidden=!ativo;if(!ativo)return;box.innerHTML=`<span class="fronts-label">EXPLORAR POR FRENTE</span><div class="fronts-tabs" role="tablist">${Object.entries(BUSINESS_VIEWS).map(([id,v])=>`<button role="tab" class="front-chip${state.view===id?' active':''}" aria-selected="${state.view===id}" data-view="${id}">${esc(v.label)}</button>`).join('')}</div>`;}
// Formatação por unidade — uma função, não um formato por card.
function frontValue(value,unit){if(value===null||value===undefined)return '—';if(unit==='money')return short(value);if(unit==='pct')return pct(value);if(unit==='int')return fmt(value);if(unit==='ratio')return fmt(value,2)+'x';if(unit==='min')return fmt(value,0)+' min';if(unit==='score')return fmt(value,2);return fmt(value,2);}
function frontCell(value,format){if(value===null||value===undefined)return '<span class="cell-empty">—</span>';if(format==='money')return money(value);if(format==='pct')return pct(value);if(format==='int')return fmt(value);if(format==='ratio')return fmt(value,2)+'x';if(format==='score')return fmt(value,2);return esc(value);}
// Subir não é bom para CAC, churn, ruptura nem custo por ticket.
function frontTone(card){if(card.delta===null||card.delta===undefined||card.direction==='neutral')return '';if(Math.abs(card.delta)<0.05)return '';const bom=card.direction==='down_good'?card.delta<0:card.delta>0;return bom?'up':'down';}
function frontCard(card){const tone=frontTone(card),unidade=card.delta_unit==='pp'?' p.p.':'%';const comparacao=card.blocked?`<small class="kpi-blocked">Aguardando definição</small>`:card.delta===null||card.delta===undefined?(card.sample?`<small>n = ${fmt(card.sample)}</small>`:'<small>Sem base anterior</small>'):`<small class="${tone}">${card.delta>=0?'+':''}${fmt(card.delta,1)}${unidade} vs. período anterior</small>`;const faisca=card.series&&card.series.filter(v=>v!==null&&v!==undefined).length>1?spark(card.series.map(v=>Number(v)||0),card.direction==='down_good'?'#b56c59':'#168f88'):'';return `<button class="kpi${card.blocked?' kpi-off':''}" data-front-kpi="${esc(card.id)}"><div class="kpi-head"><span>${esc(card.label)}</span><span>${card.blocked?'!':card.note?'i':''}</span></div><strong>${card.blocked?'—':frontValue(card.value,card.unit)}</strong><div class="kpi-bottom">${comparacao}${faisca}</div></button>`;}
function frontTable(p){return panel(esc(p.title),esc(p.subtitle),`<div class="table-wrap"><table><thead><tr>${p.columns.map(c=>`<th>${esc(c.label)}</th>`).join('')}</tr></thead><tbody>${p.rows.length?p.rows.map(r=>`<tr>${p.columns.map(c=>`<td>${frontCell(r[c.key],c.format)}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${p.columns.length}">Sem registros neste recorte.</td></tr>`}</tbody></table></div>${p.note?`<p class="panel-note">${esc(p.note)}</p>`:''}`);}
function frontBars(p){const items=p.items.filter(i=>i.value!==null&&i.value!==undefined),max=Math.max(...items.map(i=>i.value),1);return panel(esc(p.title),esc(p.subtitle),`<div class="category-bars">${items.length?items.map(i=>`<div class="category-bar-row"><span class="category-bar-label">${esc(i.name)}</span><span class="category-bar-track"><span class="category-bar-fill" style="width:${Math.max(i.value/max*100,i.value?2:0)}%"></span></span><strong>${frontValue(i.value,p.unit)}</strong></div>`).join(''):'<p>Sem registros neste recorte.</p>'}</div>${p.note?`<p class="panel-note">${esc(p.note)}</p>`:''}`);}
function frontMetricBars(p){if(!p.metrics.some(m=>m.id===state.frontMetric))state.frontMetric=p.default;const escolhido=state.frontMetric,meta=p.metrics.find(m=>m.id===escolhido),items=p.items.map(i=>({name:i.name,value:i.values[escolhido]})).filter(i=>i.value!==null&&i.value!==undefined).sort((x,y)=>y.value-x.value),max=Math.max(...items.map(i=>i.value),1);const seletor=`<label class="panel-select">KPI<select id="front-metric-kpi">${p.metrics.map(m=>`<option value="${esc(m.id)}">${esc(m.label)}</option>`).join('')}</select></label>`;return panel(esc(p.title),esc(p.subtitle),`${seletor}<div class="category-bars">${items.length?items.map(i=>`<div class="category-bar-row"><span class="category-bar-label">${esc(i.name)}</span><span class="category-bar-track"><span class="category-bar-fill" style="width:${Math.max(i.value/max*100,i.value?2:0)}%"></span></span><strong>${frontValue(i.value,meta.unit)}</strong></div>`).join(''):'<p>Sem registros neste recorte.</p>'}</div>${p.note?`<p class="panel-note">${esc(p.note)}</p>`:''}`);}
function frontPanels(panels){const html=panels.map(p=>p.type==='metric_bars'?frontMetricBars(p):p.type==='bars'?frontBars(p):frontTable(p));let out='';for(let i=0;i<html.length;i+=2)out+=`<div class="grid-main">${html[i]}${html[i+1]||''}</div>`;return out;}
function frontView(){const conf=BUSINESS_VIEWS[state.view];if(frontState.loading&&!frontState.data)return `<div class="section-intro">Carregando ${esc(conf.label)}…</div>`;if(frontState.error)return `<div class="section-intro amber"><b>${esc(conf.label)} precisa da API analítica.</b><br>${esc(frontState.error)}<br>Inicie <code>python3 -m app.server</code> na raiz do projeto. A aba Geral continua funcionando sem a API.</div>`;const d=frontState.data;if(!d)return '<div class="section-intro">Carregando…</div>';const ignorados=d.scope.filters_ignored.length?`<div class="section-intro amber"><b>Filtros que não se aplicam a esta frente:</b> ${esc(d.scope.filters_ignored.join(', '))}. ${esc(d.warnings[0]||'')}</div>`:'';const avisos=d.warnings.slice(ignorados?1:0).map(w=>`<p class="panel-note">${esc(w)}</p>`).join('');return `<div class="section-intro"><b>${esc(d.question)}</b><br>Recorte: ${esc(d.scope.label)}${d.scope.previous?` · comparado com ${esc(d.scope.previous)}`:''} · população: ${esc(d.scope.population)}</div>${ignorados}<div class="kpis kpis-front">${d.kpis.map(frontCard).join('')}</div>${frontPanels(d.panels)}${avisos}`;}
async function loadFront(){if(state.view==='general'||!FRONT_SECTIONS.includes(state.section))return;const key=frontKey();if(frontState.key===key&&frontState.data)return;frontState.key=key;frontState.view=state.view;frontState.loading=true;frontState.error=null;frontState.data=null;render(true);try{const response=await fetch(`${AI_BASE}/api/front/${state.view}?${frontQuery()}`);const data=await response.json();if(!response.ok)throw Error(data.error||`erro HTTP ${response.status}`);if(frontState.key!==key)return;frontState.data=data;}catch(error){if(frontState.key!==key)return;frontState.error=String(error.message||error).replace(/^(Error|TypeError):\s*/,'')||'API não respondeu.';}frontState.loading=false;render(true);}
function frontKpiDetail(id){const card=(frontState.data?.kpis||[]).find(k=>k.id===id);if(!card)return;const linhas=[];if(card.blocked)linhas.push(`<div class="fact"><b>Por que não há valor</b><p>${esc(card.blocked)}</p></div>`);else linhas.push(`<div class="detail-value">${frontValue(card.value,card.unit)}</div>`);if(card.previous!==null&&card.previous!==undefined)linhas.push(`<dl><dt>Período anterior</dt><dd>${frontValue(card.previous,card.unit)}</dd><dt>Variação</dt><dd>${card.delta===null?'—':`${card.delta>=0?'+':''}${fmt(card.delta,2)}${card.delta_unit==='pp'?' p.p.':'%'}`}</dd></dl>`);if(card.sample!==null&&card.sample!==undefined)linhas.push(`<p>Amostra: ${fmt(card.sample)} registros.</p>`);if(card.note)linhas.push(`<div class="fact"><b>Como ler</b><p>${esc(card.note)}</p></div>`);linhas.push(`<p>${esc(frontState.data.scope.label)} · ${esc(frontState.data.scope.population)}</p>`);drawer(esc(card.label),linhas.join(''),'DETALHE DO INDICADOR');}
document.addEventListener('click',event=>{const chip=event.target.closest('[data-view]'),card=event.target.closest('[data-front-kpi]');if(chip){const id=chip.dataset.view;if(id===state.view)return;state.view=id;frontState.data=null;frontState.error=null;frontState.key='';render();loadFront();return;}if(card)frontKpiDetail(card.dataset.frontKpi);});
// --- Frentes na aba Evolução e tendências ---------------------------------
// Na Saúde do negócio a frente responde "como está"; aqui responde "como mudou".
// Mesmo payload, outra leitura: os KPIs trazem série mensal de 2023.
function frontTrendMetrics(){return (frontState.data?.kpis||[]).filter(k=>Array.isArray(k.series)&&k.series.filter(v=>v!==null&&v!==undefined).length>1);}
function frontTrendChart(valores,rotulos,unit){const linha=unit==='pct'||unit==='ratio'||unit==='score',W=620,H=216,left=58,right=20,top=14,bottom=35,plotH=H-top-bottom,plotW=W-left-right,slots=Math.max(valores.length,1),nums=valores.map(v=>Number(v)||0);let min=Math.min(0,...nums),max=Math.max(...nums,1);const folga=(max-min)*.12||1;max+=folga;if(min<0)min-=folga;const range=max-min||1,x=i=>left+plotW*(i+.5)/slots,y=v=>top+plotH*(max-v)/range;let svg=`<svg class="chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="Série mensal"><defs><linearGradient id="frontBar" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#27a69c"/><stop offset="1" stop-color="#8cd1c7"/></linearGradient></defs>`;for(let i=0;i<=4;i++){const gy=top+plotH*i/4,v=max-range*i/4;svg+=`<line class="gridline" x1="${left}" x2="${W-right}" y1="${gy}" y2="${gy}"/><text x="${left-9}" y="${gy+3}" text-anchor="end">${esc(frontValue(v,unit))}</text>`;}if(linha){svg+=`<polyline fill="none" stroke="#168f88" stroke-width="2.5" points="${nums.map((v,i)=>`${x(i)},${y(v)}`).join(' ')}"/>`;nums.forEach((v,i)=>svg+=`<circle cx="${x(i)}" cy="${y(v)}" r="3.8" fill="white" stroke="#168f88" stroke-width="2"><title>${esc(rotulos[i])}: ${esc(frontValue(valores[i],unit))}</title></circle>`);}else{const bw=Math.min(32,plotW/slots*.47);nums.forEach((v,i)=>{const base=y(0),topo=y(v);svg+=`<rect x="${x(i)-bw/2}" y="${Math.min(base,topo)}" width="${bw}" height="${Math.max(1,Math.abs(base-topo))}" rx="4" fill="url(#frontBar)"><title>${esc(rotulos[i])}: ${esc(frontValue(valores[i],unit))}</title></rect>`;});}rotulos.forEach((r,i)=>svg+=`<text x="${x(i)}" y="${H-12}" text-anchor="middle">${esc(r)}</text>`);return svg+'</svg>';}
function frontTrendView(){const conf=BUSINESS_VIEWS[state.view];if(frontState.loading&&!frontState.data)return `<div class="section-intro">Carregando ${esc(conf.label)}…</div>`;if(frontState.error)return `<div class="section-intro amber"><b>${esc(conf.label)} precisa da API analítica.</b><br>${esc(frontState.error)}<br>Inicie <code>python3 -m app.server</code> na raiz do projeto. A frente Geral continua funcionando sem a API.</div>`;const d=frontState.data;if(!d)return '<div class="section-intro">Carregando…</div>';const metricas=frontTrendMetrics();const cabecalho=`<div class="section-intro"><b>${esc(d.question)}</b><br>Série mensal de 2023 · ${esc(d.scope.label)} · população: ${esc(d.scope.population)}</div>`;const cards=`<div class="kpis kpis-front">${d.kpis.map(frontCard).join('')}</div>`;if(!metricas.length)return `${cabecalho}<div class="section-intro amber"><b>Esta frente não tem série temporal.</b><br>${esc(d.warnings[0]||'')}<br>Os indicadores continuam disponíveis na Saúde do negócio.</div>${cards}`;const escolhido=metricas.some(m=>m.id===state.frontTrendMetric)?state.frontTrendMetric:metricas[0].id;const kpi=metricas.find(m=>m.id===escolhido);const valores=kpi.series.map(v=>v===null||v===undefined?0:v),vazios=kpi.series.filter(v=>v===null||v===undefined).length;const seletor=`<label class="panel-select">KPI<select id="front-trend-kpi">${metricas.map(m=>`<option value="${esc(m.id)}">${esc(m.label)}</option>`).join('')}</select></label>`;const grafico=panel(`${esc(kpi.label)} ao longo de 2023`,'Mesma população e filtros do recorte; a série cobre os doze meses',`${seletor}<div class="legend"><span><i style="background:#168f88"></i>${esc(kpi.label)}</span></div><div class="chart-wrap">${frontTrendChart(valores,MONTHS,kpi.unit)}</div><div class="chart-caption"><span>Eixo: ${esc(kpi.label)}</span><span>Série mensal, independente do período filtrado</span></div>${vazios?`<p class="panel-note">${vazios} ${vazios===1?'mês sem valor calculável':'meses sem valor calculável'} neste recorte; aparecem como zero no gráfico.</p>`:''}`);const tabela=panel('Valores mensais','Os mesmos números do gráfico, em tabela',`<div class="table-wrap"><table><thead><tr><th>MÊS</th>${metricas.map(m=>`<th>${esc(m.label.toUpperCase())}</th>`).join('')}</tr></thead><tbody>${MONTHS.map((mes,i)=>`<tr><td>${mes}</td>${metricas.map(m=>`<td>${frontCell(m.series[i],m.unit==='money'?'money':m.unit==='pct'?'pct':m.unit==='ratio'?'ratio':m.unit==='score'?'score':'int')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`);return `${cabecalho}${cards}<div class="grid-main">${grafico}${tabela}</div>`;}
// --- Alertas prioritários -------------------------------------------------
// A avaliação é do servidor (app/alerts.py): regra, materialidade, persistência
// e severidade vivem num lugar só. A tela renderiza e explica.
const alertState={key:'',data:null,loading:false,error:null};
function alertKey(){return frontKey().replace(/^\{"v":"[a-z]+"/,'{"v":"alerts"');}
async function loadAlerts(){const chave=alertKey();if(alertState.key===chave&&alertState.data)return;alertState.key=chave;alertState.loading=true;alertState.error=null;alertState.data=null;render(true);try{const resposta=await fetch(`${AI_BASE}/api/alerts?${frontQuery()}`);const dados=await resposta.json();if(!resposta.ok)throw Error(dados.error||`erro HTTP ${resposta.status}`);if(alertState.key!==chave)return;alertState.data=dados;}catch(erro){if(alertState.key!==chave)return;alertState.error=String(erro.message||erro).replace(/^(Error|TypeError):\s*/,'')||'API não respondeu.';}alertState.loading=false;render(true);}
const ALERT_TONE={'Crítica':'','Alta':'purple','Moderada':'amber','Informativa':'teal'};
// Período anterior independente do seletor "Comparação": a investigação com IA
// precisa da base anterior mesmo quando o gestor desligou a comparação na tela.
function priorPeriod(){if(state.grain==='year')return null;if(state.grain==='quarter'){const q=Number(state.period.slice(-1));return q===1?null:aggregate(rows(state.channel,[(q-2)*3+1,(q-2)*3+2,(q-2)*3+3]));}if(state.grain==='month'){const m=Number(state.period.slice(-2));return m===1?null:aggregate(rows(state.channel,[m-1]));}const week=Number(state.period.slice(-2));if(week<=1||weekPartial())return null;const [start]=rangeFor(),end=new Date(`${start}T00:00:00Z`),begin=new Date(end);begin.setUTCDate(begin.getUTCDate()-7);return aggregate(rowsBetween(begin.toISOString().slice(0,10),end.toISOString().slice(0,10)));}
function alertEvidence(itens){return `<dl>${itens.map(i=>`<dt>${esc(i.rotulo)}</dt><dd>${i.unidade==='pp'?`${fmt(i.valor,2)} p.p.`:frontCell(i.valor,i.unidade)}</dd>`).join('')}</dl>`;}
function alertCardHtml(a,indice){const pers=a.persistence||{};const selo=pers.estado==='repetida'?'<span class="pill purple">Repetida</span>':pers.estado==='pontual'?'<span class="pill">Pontual</span>':'';return `<button class="alert-card ${a.severity==='Crítica'?'crítica':a.severity.toLowerCase()}" data-alert-index="${indice}"><span class="alert-priority">${esc(a.severity)}</span><div><h3>${esc(a.title)}</h3><p>${esc(a.explanation)}</p><small>${esc(a.rule)} · ${esc(a.entity)}${a.impact!==null&&a.impact!==undefined?` · impacto diagnóstico ${money(a.impact)}`:''} ${selo}</small></div><span class="arrow">→</span></button>`;}
function alertDetail(indice){const a=(alertState.data?.alerts||[])[indice];if(!a)return;const pers=a.persistence||{};drawer(esc(a.title),`<span class="pill ${ALERT_TONE[a.severity]||''}">${esc(a.severity)}</span> <span class="pill">${esc(a.rule)} ${esc(a.version)}</span><p>${esc(alertState.data.scope.label)} · ${esc(alertState.data.scope.population)}</p>${alertEvidence(a.evidence)}<div class="fact"><b>Como a regra chegou aqui</b><p>${esc(a.explanation)}</p></div><div class="fact"><b>Persistência</b><p>${esc(pers.motivo||'não avaliada')}</p></div><div class="divider"></div><p><b>Limitações</b></p><ul class="ai-list">${a.limitations.map(l=>`<li>${esc(l)}</li>`).join('')}</ul>${a.navigate&&a.navigate.section?`<div class="detail-actions"><button class="primary" data-alert-go="${indice}">Investigar no recorte</button></div>`:''}`,'EVIDÊNCIA DO ALERTA');}
function alertRuleTable(regras){return panel('Catálogo de regras','Uma família que não publicou hoje pode não ter sido avaliada; a diferença importa',`<div class="table-wrap"><table><thead><tr><th>ID</th><th>FAMÍLIA</th><th>PUBLICADOS</th><th>ESTADO</th></tr></thead><tbody>${regras.map(r=>`<tr><td>${esc(r.id)}</td><td>${esc(r.name)}<br><small style="color:#9ba5b4">${esc(r.purpose)}</small></td><td>${r.published?`<b>${r.published}</b>`:'—'}</td><td>${esc(r.state)}</td></tr>`).join('')}</tbody></table></div>`);}
function alerts(){if(alertState.loading&&!alertState.data)return '<div class="section-intro">Avaliando as regras…</div>';if(alertState.error)return `<div class="section-intro amber"><b>Os alertas precisam da API analítica.</b><br>${esc(alertState.error)}<br>Inicie <code>python3 -m app.server</code> na raiz do projeto.</div>`;const d=alertState.data;if(!d)return '<div class="section-intro">Avaliando as regras…</div>';const publicados=d.alerts.filter(a=>a.severity!=='Informativa'),avisos=d.alerts.filter(a=>a.severity==='Informativa');const p=d.parameters;const resumo=`<div class="alert-summary"><div><span>ALERTAS PUBLICADOS</span><strong>${publicados.length}</strong></div><div><span>MATERIALIDADE</span><strong>${money(p.materialidade_brl)}</strong></div><div><span>QUEDA DE MARGEM</span><strong>${fmt(p.queda_margem_pp,1)} p.p.</strong></div><div><span>PERSISTÊNCIA</span><strong>${esc(p.persistencia)}</strong></div></div>`;const lista=publicados.length?publicados.map((a,i)=>alertCardHtml(a,d.alerts.indexOf(a))).join(''):`<div class="empty"><span class="empty-icon">✓</span><h3>Nenhum alerta elegível neste recorte</h3><p>Nenhuma condição superou a materialidade e as tolerâncias vigentes. Isso não comprova que não existam outros problemas — veja no catálogo abaixo quais regras foram avaliadas.</p></div>`;const bloco=panel('O que merece atenção','Clique em um alerta para abrir a evidência e as limitações',`<div class="alert-list">${lista}</div><p class="panel-note">Parâmetros: ${esc(p.origem)}.</p>`);const informativos=avisos.length?`<div style="margin-top:18px">${panel('Confiabilidade do dado','Aviso separado de oportunidade financeira, como pede o contrato analítico',`<div class="alert-list">${avisos.map(a=>alertCardHtml(a,d.alerts.indexOf(a))).join('')}</div>`)}</div>`:'';return `${resumo}${bloco}${informativos}<div style="margin-top:18px">${alertRuleTable(d.rules)}</div>`;}
document.addEventListener('click',evento=>{const abrir=evento.target.closest('[data-alert-index]'),ir=evento.target.closest('[data-alert-go]');if(ir){const a=(alertState.data?.alerts||[])[Number(ir.dataset.alertGo)];$('detail').close();if(!a)return;const n=a.navigate||{};if(n.channel){state.channel=n.channel;$('channel').value=n.channel;}if(n.category){state.category=n.category;$('category').value=n.category;}if(n.metric)state.trendMetric=n.metric;if(n.view)state.view=n.view;navigate(n.section||'tendencias');return;}if(abrir)alertDetail(Number(abrir.dataset.alertIndex));});
// Bootstrap por ultimo: o bloco de frentes declara const/let que o render consulta.
state.section=SECTIONS[location.hash.slice(1)]?location.hash.slice(1):'saude';render();
